2	
3	import com.example.starter.compliance.repo.ComplianceRepository;
4	import java.math.BigDecimal;
5	import org.springframework.boot.ApplicationArguments;
6	import org.springframework.boot.ApplicationRunner;
7	import org.springframework.core.annotation.Order;
8	import org.springframework.stereotype.Component;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	/**
12	 * 合成基础数据初始化（幂等执行，仅写入目录与初始限量，不写入任何配方/备案业务数据）：
13	 * <ul>
14	 *   <li>食品分类：BEV01 风味饮料、BAK01 糕点、MEAT01 熟肉制品；</li>
15	 *   <li>添加剂：E202 山梨酸钾/防腐剂、E211 苯甲酸钠/防腐剂、E102 柠檬黄/着色剂、
16	 *       E129 诱惑红/着色剂、E300 抗坏血酸/抗氧化剂；</li>
17	 *   <li>复合配料：ING_SAUCE 复合调味酱（含 E202 2.0 g/kg、E211 4.0 g/kg）、
18	 *       ING_SYRUP 果味糖浆（含 E102 0.5 g/kg）；</li>
19	 *   <li>初始限量（g/kg 终产品）：BEV01 下 E202=0.5、E211=1.0、E102=0.1、E129=0.1、E300=0.5；
20	 *       BAK01 下 E202=1.0、E211=1.0、E300=2.0；MEAT01 下 E202=1.5、E300=0.5。</li>
21	 * </ul>
22	 */
23	@Component
24	@Order(0)
25	public class SyntheticDataInitializer implements ApplicationRunner {
26	
27	    private final ComplianceRepository repository;
28	
29	    public SyntheticDataInitializer(ComplianceRepository repository) {
30	        this.repository = repository;
31	    }
32	
33	    @Override
34	    @Transactional
35	    public void run(ApplicationArguments args) {
36	        if (repository.countCategories() > 0) {
37	            return;
38	        }
39	
40	        repository.insertCategory("BEV01", "风味饮料");
41	        repository.insertCategory("BAK01", "糕点");
42	        repository.insertCategory("MEAT01", "熟肉制品");
43	
44	        repository.insertAdditive("E202", "山梨酸钾", "PRESERVATIVE");
45	        repository.insertAdditive("E211", "苯甲酸钠", "PRESERVATIVE");
46	        repository.insertAdditive("E102", "柠檬黄", "COLORANT");
47	        repository.insertAdditive("E129", "诱惑红", "COLORANT");
48	        repository.insertAdditive("E300", "抗坏血酸", "ANTIOXIDANT");
49	
50	        repository.insertIngredient("ING_SAUCE", "复合调味酱");
51	        repository.insertIngredient("ING_SYRUP", "果味糖浆");
52	        repository.insertIngredientAdditive("ING_SAUCE", "E202", new BigDecimal("2.000000"));
53	        repository.insertIngredientAdditive("ING_SAUCE", "E211", new BigDecimal("4.000000"));
54	        repository.insertIngredientAdditive("ING_SYRUP", "E102", new BigDecimal("0.500000"));
55	
56	        long now = System.currentTimeMillis();
57	        repository.insertLimit("E202", "BEV01", new BigDecimal("0.500000"), now);
58	        repository.insertLimit("E211", "BEV01", new BigDecimal("1.000000"), now);
59	        repository.insertLimit("E102", "BEV01", new BigDecimal("0.100000"), now);
60	        repository.insertLimit("E129", "BEV01", new BigDecimal("0.100000"), now);
61	        repository.insertLimit("E300", "BEV01", new BigDecimal("0.500000"), now);
62	        repository.insertLimit("E202", "BAK01", new BigDecimal("1.000000"), now);
63	        repository.insertLimit("E211", "BAK01", new BigDecimal("1.000000"), now);
64	        repository.insertLimit("E300", "BAK01", new BigDecimal("2.000000"), now);
65	        repository.insertLimit("E202", "MEAT01", new BigDecimal("1.500000"), now);
66	        repository.insertLimit("E300", "MEAT01", new BigDecimal("0.500000"), now);
67	    }
68	}
