36	class ComplianceApiIntegrationTest {
37	
38	    private static final LocalDate DAY_0 = LocalDate.of(2026, 3, 1);
39	
40	    @LocalServerPort
41	    private int port;
42	
43	    @Autowired
44	    private TestRestTemplate restTemplate;
45	
46	    @Autowired
47	    private ComplianceRepository repository;
48	
49	    @Autowired
50	    private ComplianceClock clock;
51	
52	    private final ObjectMapper mapper = new ObjectMapper();
53	
54	    @BeforeEach
55	    void clean() {
56	        repository.deleteBusinessData();
57	        repository.updateLimit("E202", "BEV01", new BigDecimal("0.500000"),
58	                System.currentTimeMillis());
59	        clock.reset();
60	    }
61	
62	    /** 将可控时钟设置到某 UTC 日期正午，避免 UTC 日界抖动。 */
63	    private void setUtcDate(LocalDate date) {
64	        clock.setFixed(date.atTime(12, 0).toInstant(java.time.ZoneOffset.UTC));
65	    }
66	
67	    private String url(String path) {
68	        return "http://localhost:" + port + "/api/compliance" + path;
69	    }
70	
71	    private HttpHeaders jsonHeaders() {
72	        HttpHeaders headers = new HttpHeaders();
73	        headers.setContentType(MediaType.APPLICATION_JSON);
74	        return headers;
75	    }
76	
77	    @SuppressWarnings("unchecked")
78	    private Map<String, Object> body(String requestId, Map<String, Object> fields) {
79	        Map<String, Object> body = new java.util.LinkedHashMap<>(fields);
80	        body.put("requestId", requestId);
81	        return body;
82	    }
83	
84	    @Test
85	    void fullHttpWorkflowWithReplayConflictAndCancellation() throws Exception {
86	        setUtcDate(DAY_0);
87	        String requestId = Fixtures.requestId();
88	        Map<String, Object> formula = body(requestId, Map.of(
89	                "productCode", "P-HTTP",
90	                "productName", "HTTP 全链路产品",
91	                "categoryCode", "BEV01",
92	                "version", 1,
93	                "additives", List.of(Map.of("additiveCode", "E202", "amount", new BigDecimal("0.3"))),
94	                "ingredients", List.of()));
95	
96	        // 1. 提交
97	        ResponseEntity<String> submit = restTemplate.postForEntity(url("/formulas"),
98	                new HttpEntity<>(mapper.writeValueAsString(formula), jsonHeaders()), String.class);
99	        assertThat(submit.getStatusCode()).isEqualTo(HttpStatus.OK);
100	        JsonNode submitted = mapper.readTree(submit.getBody());
101	        long formulaId = submitted.get("formulaId").asLong();
102	        assertThat(submitted.get("state").asText()).isEqualTo("SUBMITTED");
103	
104	        // 2. 同键重放：同参返回首次结果，响应头标记重放。
105	        ResponseEntity<String> replay = restTemplate.postForEntity(url("/formulas"),
106	                new HttpEntity<>(mapper.writeValueAsString(formula), jsonHeaders()), String.class);
107	        assertThat(replay.getStatusCode()).isEqualTo(HttpStatus.OK);
108	        assertThat(replay.getHeaders().getFirst("X-Idempotent-Replay")).isEqualTo("true");
109	        assertThat(mapper.readTree(replay.getBody()).get("replayed").asBoolean()).isTrue();
110	        assertThat(mapper.readTree(replay.getBody()).get("formulaId").asLong()).isEqualTo(formulaId);
111	
112	        // 3. 同键异参：409 且错误码稳定。
113	        Map<String, Object> conflictParams = body(requestId, Map.of(
114	                "productCode", "P-HTTP",
115	                "productName", "HTTP 全链路产品",
116	                "categoryCode", "BEV01",
117	                "version", 1,
118	                "additives", List.of(Map.of("additiveCode", "E202", "amount", new BigDecimal("0.45"))),
119	                "ingredients", List.of()));
120	        ResponseEntity<String> conflict = restTemplate.postForEntity(url("/formulas"),
121	                new HttpEntity<>(mapper.writeValueAsString(conflictParams), jsonHeaders()),
122	                String.class);
123	        assertThat(conflict.getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
124	        assertThat(mapper.readTree(conflict.getBody()).get("code").asText())
125	                .isEqualTo("REQUEST_PARAM_CONFLICT");
126	
127	        // 4. 审查通过
128	        ResponseEntity<String> review = post("/formulas/review",
129	                body(Fixtures.requestId(), Map.of("formulaId", formulaId)));
130	        assertThat(review.getStatusCode()).isEqualTo(HttpStatus.OK);
131	        JsonNode reviewNode = mapper.readTree(review.getBody());
132	        assertThat(reviewNode.get("report").get("passed").asBoolean()).isTrue();
133	
134	        // 5. 批准（版本冻结）
135	        ResponseEntity<String> approve = post("/formulas/approve",
136	                body(Fixtures.requestId(), Map.of("formulaId", formulaId)));
137	        assertThat(approve.getStatusCode()).isEqualTo(HttpStatus.OK);
138	        assertThat(mapper.readTree(approve.getBody()).get("state").asText()).isEqualTo("APPROVED");
139	
140	        // 6. 量产备案 ACTIVE
141	        ResponseEntity<String> filed = post("/filings",
142	                body(Fixtures.requestId(), Map.of("formulaId", formulaId)));
143	        assertThat(filed.getStatusCode()).isEqualTo(HttpStatus.OK);
144	        JsonNode filingNode = mapper.readTree(filed.getBody());
145	        long filingId = filingNode.get("filingId").asLong();
146	        assertThat(filingNode.get("status").asText()).isEqualTo("ACTIVE");
147	
148	        // 7. 标准收紧 0.5→0.4：受影响备案进入复审观察。
149	        ResponseEntity<String> standard = post("/standards",
150	                body(Fixtures.requestId(), Map.of(
151	                        "additiveCode", "E202",
152	                        "categoryCode", "BEV01",
153	                        "maxAmount", new BigDecimal("0.4"))));
154	        assertThat(standard.getStatusCode()).isEqualTo(HttpStatus.OK);
155	        JsonNode standardNode = mapper.readTree(standard.getBody());
156	        assertThat(standardNode.get("watchFilingIds").get(0).asLong()).isEqualTo(filingId);
157	
158	        ResponseEntity<String> watched = restTemplate.getForEntity(url("/filings/" + filingId),
159	                String.class);
160	        JsonNode watchedNode = mapper.readTree(watched.getBody());
161	        assertThat(watchedNode.get("status").asText()).isEqualTo("REVIEW_WATCH");
162	        assertThat(watchedNode.get("daysRemaining").asLong()).isEqualTo(90L);
163	
164	        // 8. 恰第 90 个 UTC 自然日复审受理并恢复 ACTIVE（0.3 ≤ 0.4）。
165	        setUtcDate(DAY_0.plusDays(90));
166	        ResponseEntity<String> reReview = post("/filings/review",
167	                body(Fixtures.requestId(), Map.of("filingId", filingId)));
168	        assertThat(reReview.getStatusCode()).isEqualTo(HttpStatus.OK);
169	        assertThat(mapper.readTree(reReview.getBody()).get("status").asText()).isEqualTo("ACTIVE");
170	
171	        // 9. 注销为终态，再次注销幂等；注销后量产上报 410。
172	        String cancelKey = Fixtures.requestId();
173	        Map<String, Object> cancelBody = body(cancelKey, Map.of("filingId", filingId));
174	        ResponseEntity<String> cancel = post("/filings/cancel", cancelBody);
175	        assertThat(cancel.getStatusCode()).isEqualTo(HttpStatus.OK);
176	        ResponseEntity<String> cancelReplay = post("/filings/cancel", cancelBody);
177	        assertThat(cancelReplay.getStatusCode()).isEqualTo(HttpStatus.OK);
178	        assertThat(mapper.readTree(cancelReplay.getBody()).get("replayed").asBoolean()).isTrue();
179	
180	        ResponseEntity<String> production = post("/production-records",
181	                body(Fixtures.requestId(), Map.of(
182	                        "filingId", filingId,
183	                        "batchNo", "B-HTTP-1",
184	                        "quantityKg", new BigDecimal("12.5"))));
185	        assertThat(production.getStatusCode()).isEqualTo(HttpStatus.GONE);
186	        assertThat(mapper.readTree(production.getBody()).get("code").asText())
187	                .isEqualTo("FILING_CANCELLED");
188	
189	        // 10. 版本轨迹可复算、查询稳定。
190	        ResponseEntity<String> trajectory =
191	                restTemplate.getForEntity(url("/products/P-HTTP/trajectory"), String.class);
192	        assertThat(trajectory.getStatusCode()).isEqualTo(HttpStatus.OK);
193	        JsonNode trajectoryNode = mapper.readTree(trajectory.getBody());
194	        assertThat(trajectoryNode.get("formulas")).hasSize(1);
195	        assertThat(trajectoryNode.get("filings")).hasSize(1);
196	        ResponseEntity<String> trajectoryAgain =
197	                restTemplate.getForEntity(url("/products/P-HTTP/trajectory"), String.class);
198	        assertThat(trajectoryAgain.getBody()).isEqualTo(trajectory.getBody());
199	    }
200	
201	    @Test
202	    void carriedOverViolationReturnsPassedFalseAndWholeOrderRejected() throws Exception {
203	        Map<String, Object> formula = body(Fixtures.requestId(), Map.of(
204	                "productCode", "P-HTTP-FAIL",
205	                "productName", "带入超限产品",
206	                "categoryCode", "BEV01",
207	                "version", 1,
208	                "additives", List.of(),
209	                "ingredients", List.of(Map.of(
210	                        "ingredientCode", "ING_SAUCE", "ratio", new BigDecimal("0.3")))));
211	        ResponseEntity<String> submit = post("/formulas", formula);
212	        long formulaId = mapper.readTree(submit.getBody()).get("formulaId").asLong();
213	
214	        ResponseEntity<String> review = post("/formulas/review",
215	                body(Fixtures.requestId(), Map.of("formulaId", formulaId)));
216	        assertThat(review.getStatusCode()).isEqualTo(HttpStatus.OK);
217	        JsonNode report = mapper.readTree(review.getBody()).get("report");
218	        assertThat(report.get("passed").asBoolean()).isFalse();
219	        assertThat(report.get("items").get(0).get("reason").asText()).isEqualTo("OVER_LIMIT");
220	
221	        // 违例配方不能批准：409。
222	        ResponseEntity<String> approve = post("/formulas/approve",
223	                body(Fixtures.requestId(), Map.of("formulaId", formulaId)));
224	        assertThat(approve.getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
225	    }
226	
227	    private ResponseEntity<String> post(String path, Map<String, Object> requestBody)
228	            throws Exception {
229	        return restTemplate.postForEntity(url(path),
230	                new HttpEntity<>(mapper.writeValueAsString(requestBody), jsonHeaders()),
231	                String.class);
232	    }
233	}
