        // 覆盖不足（仅清 MILK，遗留 MILK+EGG）：422，不消耗。
        long milkOnly = lineService.confirmCertificate(certificate("L-B", List.of(MILK),
                confirmedAt - 100, confirmedAt)).body().certificateId();
